script:
(function () {
  'use strict';
  // ---- Historical price data -------------------------------------------------------------
  // CPI-U, U.S. city average, all items, not seasonally adjusted, 1982-84 = 100: annual averages
  // as published by the U.S. Bureau of Labor Statistics (series CUUR0000SA0, period M13).
  // Source: https://data.bls.gov/timeseries/CUUR0000SA0 (retrieved 1 October 2026).
  // First year 1913, last year 2025. BLS publishes annual averages to one decimal before 2007
  // and to three decimals from 2007; values are kept exactly as published. The 2025 average
  // is the official BLS figure (October 2025 was not collected during the funding lapse).
  // Update once a year when BLS publishes the next annual average (mid-January).
  // (Copied unchanged from inflation-calculator.json; keep the two in step.)
  var CPI_FIRST_YEAR = 1913;
  var CPI = [
    9.9, 10.0, 10.1, 10.9, 12.8, 15.1, 17.3, 20.0, 17.9, 16.8,  // 1913-1922
    17.1, 17.1, 17.5, 17.7, 17.4, 17.1, 17.1, 16.7, 15.2, 13.7,  // 1923-1932
    13.0, 13.4, 13.7, 13.9, 14.4, 14.1, 13.9, 14.0, 14.7, 16.3,  // 1933-1942
    17.3, 17.6, 18.0, 19.5, 22.3, 24.1, 23.8, 24.1, 26.0, 26.5,  // 1943-1952
    26.7, 26.9, 26.8, 27.2, 28.1, 28.9, 29.1, 29.6, 29.9, 30.2,  // 1953-1962
    30.6, 31.0, 31.5, 32.4, 33.4, 34.8, 36.7, 38.8, 40.5, 41.8,  // 1963-1972
    44.4, 49.3, 53.8, 56.9, 60.6, 65.2, 72.6, 82.4, 90.9, 96.5,  // 1973-1982
    99.6, 103.9, 107.6, 109.6, 113.6, 118.3, 124.0, 130.7, 136.2, 140.3,  // 1983-1992
    144.5, 148.2, 152.4, 156.9, 160.5, 163.0, 166.6, 172.2, 177.1, 179.9,  // 1993-2002
    184.0, 188.9, 195.3, 201.6, 207.342, 215.303, 214.537, 218.056, 224.939, 229.594,  // 2003-2012
    232.957, 236.736, 237.017, 240.007, 245.120, 251.107, 255.657, 258.811, 270.970, 292.655,  // 2013-2022
    304.702, 313.689, 321.943  // 2023-2025
  ];
  var CPI_LAST_YEAR = CPI_FIRST_YEAR + CPI.length - 1;
  // ----------------------------------------------------------------------------------------
  // An investment P held from the start year to the end year (n = end - start years, measured
  // between annual-average CPI values). Nominal growth: return mode E = P x (1 + r)^n; ending
  // value mode r = (E / P)^(1/n) - 1. Inflation factor k = CPI(end) / CPI(start).
  // Real value in start-year dollars = E / k; balance that only kept pace with inflation = P x k;
  // real annual return = ((E / P) / k)^(1/n) - 1 = (1 + r) / (1 + inflation) - 1.
  // CHECKS (Node, scratch tests/ih.test.js): k(1980 -> 2025) = 321.943 / 82.4 = 3.90707, so
  // $10,000 needed $39,070.75 in 2025 to keep pace; average inflation 3.0747% a year; $10,000 at
  // 6% for 45 years = $137,646.11, worth $35,229.96 in 1980 dollars, real return 2.8380% a year
  // (1.06 / 1.030747 - 1); ending-value mode with $137,646.11 gives back 6.00%; 0% return gives a real value of
  // $2,559.46 (10,000 / 3.90707); 2008 -> 2009 (deflation) gives a real return above the nominal.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 2 });
  var IDS = ['ihReal', 'ihNominal', 'ihRealRate', 'ihInflation', 'ihNomRate', 'ihCumulative', 'ihKeepPace', 'ihPower', 'ihRealGain'];

  function num(id) {
    var v = parseFloat(document.getElementById(id).value);
    return isNaN(v) ? NaN : v;
  }
  function cpi(year) { return CPI[year - CPI_FIRST_YEAR]; }
  function cpiText(year) { return cpi(year).toFixed(year < 2007 ? 1 : 3); }
  function pct(x, d) { return (x * 100).toFixed(d) + '%'; }
  function set(id, text) { document.getElementById(id).textContent = text; }
  function signed(x) { return (x < 0 ? '−' : '') + money.format(Math.abs(x)); }

  function analyze(P, start, end, mode, rate, endValue) {
    var n = end - start, k = cpi(end) / cpi(start);
    var r = mode === 'value' ? (endValue > 0 ? Math.pow(endValue / P, 1 / n) - 1 : -1) : rate;
    var E = mode === 'value' ? endValue : P * Math.pow(1 + r, n);
    var rows = [];
    for (var y = start; y <= end; y++) {
      var bal = P * Math.pow(1 + r, y - start);
      rows.push({ year: y, cpi: cpi(y), change: y > CPI_FIRST_YEAR ? cpi(y) / cpi(y - 1) - 1 : NaN,
                  balance: bal, pace: P * cpi(y) / cpi(start), real: bal * cpi(start) / cpi(y) });
    }
    return { n: n, k: k, rate: r, end: E, real: E / k, keepPace: P * k,
             realRate: E > 0 ? Math.pow(E / P / k, 1 / n) - 1 : -1,
             inflation: Math.pow(k, 1 / n) - 1, rows: rows };
  }

  function update() {
    var mode = document.getElementById('ihMode').value;
    document.getElementById('ihWrapRate').hidden = mode === 'value';
    document.getElementById('ihWrapValue').hidden = mode !== 'value';
    var P = num('ihAmount'), start = parseInt(document.getElementById('ihStart').value, 10),
        end = parseInt(document.getElementById('ihEnd').value, 10), rate = num('ihRate'), endValue = num('ihEndValue');
    var error = document.getElementById('ihError'), msg = '';
    if (isNaN(P) || P <= 0) msg = 'Enter a starting balance above $0.';
    else if (isNaN(start) || isNaN(end) || start < CPI_FIRST_YEAR || end > CPI_LAST_YEAR || start >= end)
      msg = 'Choose an ending year after the starting year (' + CPI_FIRST_YEAR + ' to ' + CPI_LAST_YEAR + ').';
    else if (mode !== 'value' && (isNaN(rate) || rate < -50 || rate > 100)) msg = 'Enter an annual return from -50% to 100%.';
    else if (mode === 'value' && (isNaN(endValue) || endValue < 0)) msg = 'Enter an ending value of $0 or more.';
    error.hidden = !msg;
    if (msg) {
      error.textContent = msg;
      IDS.forEach(function (id) { set(id, '–'); });
      set('ihSummary', '');
      document.getElementById('ihTable').innerHTML = '';
      return;
    }
    var a = analyze(P, start, end, mode, rate / 100, endValue);
    set('ihRealLabel', 'Real value in ' + start + ' dollars');
    set('ihNominalLabel', 'Ending value in ' + end);
    set('ihRealColumn', 'Value in ' + start + ' dollars');
    set('ihReal', money.format(a.real));
    set('ihNominal', money.format(a.end));
    set('ihRealRate', pct(a.realRate, 2));
    set('ihInflation', pct(a.inflation, 2));
    set('ihNomRate', pct(a.rate, 2));
    set('ihCumulative', pct(a.k - 1, 1));
    set('ihKeepPace', money.format(a.keepPace));
    set('ihPower', signed(a.end - a.keepPace));
    set('ihRealGain', signed(a.real - P));
    set('ihSummary', 'Prices rose ' + pct(a.k - 1, 1) + ' from ' + start + ' to ' + end + ', so ' + money.format(P) +
        ' had to grow to ' + money.format(a.keepPace) + ' just to buy the same things. ' +
        (a.end >= a.keepPace ? 'This investment beat inflation by ' : 'This investment fell short of inflation by ') +
        money.format(Math.abs(a.end - a.keepPace)) + ' in ' + end + ' dollars.');
    document.getElementById('ihTable').innerHTML = a.rows.map(function (row) {
      return '<tr><td>' + row.year + '</td><td>' + cpiText(row.year) + '</td><td>' + (isNaN(row.change) ? '–' : pct(row.change, 1)) +
             '</td><td>' + money.format(row.balance) + '</td><td>' + money.format(row.pace) + '</td><td>' + money.format(row.real) + '</td></tr>';
    }).join('');
  }

  document.addEventListener('DOMContentLoaded', function () {
    set('ihDataNote', 'Uses BLS CPI-U annual averages from ' + CPI_FIRST_YEAR + ' to ' + CPI_LAST_YEAR + '.');
    var form = document.getElementById('ihForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
